//! CodeYourPCB Core
//!
//! Shared types, coordinates, and geometry primitives for the CodeYourPCB system.
//! All coordinates use integer nanometers (i64) for deterministic precision.
//!
//! # Why Integer Nanometers?
//!
//! PCB tools commonly face issues with floating-point accumulation errors.
//! Small precision errors compound across complex routing operations, leading to:
//! - Traces that should connect but don't (off by sub-micron amounts)
//! - Non-deterministic DRC results
//! - Different output from the same input file
//!
//! By using i64 nanometers internally:
//! - All coordinate arithmetic is exact
//! - Same input always produces identical output
//! - Comparisons and hashing are reliable
//! - Range is sufficient (i64 max = ~9.2 billion meters)
//!
//! # Coordinate System
//!
//! - Origin: bottom-left of the board
//! - X-axis: positive right
//! - Y-axis: positive up (mathematical convention)
//!
//! This matches standard mathematical conventions and most Gerber viewers.
//!
//! # Unit Conversions
//!
//! | Unit | Nanometers |
//! |------|------------|
//! | 1 mm | 1,000,000 |
//! | 1 mil | 25,400 |
//! | 1 inch | 25,400,000 |
//!
//! # Modules
//!
//! - [`coords`]: Core coordinate types ([`Nm`], [`Point`])
//! - [`units`]: Unit parsing and conversion ([`Unit`])
//! - [`geometry`]: Geometric primitives ([`Rect`])

pub mod coords;
pub mod geometry;
pub mod units;

// Re-export primary types at crate root for convenience
pub use coords::{Nm, Point, NM_PER_INCH, NM_PER_MIL, NM_PER_MM};
pub use geometry::Rect;
pub use units::{Dimension, ParseUnitError, Unit};

//! Unit types for dimension parsing.
//!
//! This module provides the [`Unit`] enum for representing and converting
//! between different measurement units used in PCB design.

use crate::coords::{Nm, NM_PER_INCH, NM_PER_MIL, NM_PER_MM};
use serde::{Deserialize, Serialize};
use std::str::FromStr;
use thiserror::Error;

/// A unit of measurement for PCB dimensions.
///
/// Used for parsing dimensions from the DSL and converting to internal
/// nanometer representation.
///
/// # Examples
///
/// ```
/// use cypcb_core::{Unit, Nm};
///
/// let unit = Unit::Mm;
/// let nm = unit.to_nm(10.0);
/// assert_eq!(nm.0, 10_000_000);
/// ```
#[derive(Debug, Default, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Unit {
    /// Millimeters (1 mm = 1,000,000 nm)
    #[default]
    Mm,
    /// Mils / thousandths of an inch (1 mil = 25,400 nm)
    Mil,
    /// Inches (1 inch = 25,400,000 nm)
    Inch,
    /// Nanometers (native unit)
    Nm,
}

impl Unit {
    /// Convert a value in this unit to nanometers.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::Unit;
    ///
    /// assert_eq!(Unit::Mm.to_nm(1.0).0, 1_000_000);
    /// assert_eq!(Unit::Mil.to_nm(1.0).0, 25_400);
    /// assert_eq!(Unit::Inch.to_nm(1.0).0, 25_400_000);
    /// assert_eq!(Unit::Nm.to_nm(100.0).0, 100);
    /// ```
    #[inline]
    pub fn to_nm(self, value: f64) -> Nm {
        let nm = match self {
            Unit::Mm => (value * NM_PER_MM as f64).round() as i64,
            Unit::Mil => (value * NM_PER_MIL as f64).round() as i64,
            Unit::Inch => (value * NM_PER_INCH as f64).round() as i64,
            Unit::Nm => value.round() as i64,
        };
        Nm(nm)
    }

    /// Convert a nanometer value to this unit.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::{Unit, Nm};
    ///
    /// let nm = Nm(1_000_000);
    /// assert!((Unit::Mm.from_nm(nm) - 1.0).abs() < 1e-9);
    /// ```
    #[inline]
    pub fn from_nm(self, nm: Nm) -> f64 {
        match self {
            Unit::Mm => nm.0 as f64 / NM_PER_MM as f64,
            Unit::Mil => nm.0 as f64 / NM_PER_MIL as f64,
            Unit::Inch => nm.0 as f64 / NM_PER_INCH as f64,
            Unit::Nm => nm.0 as f64,
        }
    }

    /// Get the suffix string for this unit.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::Unit;
    ///
    /// assert_eq!(Unit::Mm.suffix(), "mm");
    /// assert_eq!(Unit::Mil.suffix(), "mil");
    /// ```
    pub const fn suffix(self) -> &'static str {
        match self {
            Unit::Mm => "mm",
            Unit::Mil => "mil",
            Unit::Inch => "in",
            Unit::Nm => "nm",
        }
    }

    /// Get the nanometers per unit.
    ///
    /// Returns 1 for nanometers.
    pub const fn nm_per_unit(self) -> i64 {
        match self {
            Unit::Mm => NM_PER_MM,
            Unit::Mil => NM_PER_MIL,
            Unit::Inch => NM_PER_INCH,
            Unit::Nm => 1,
        }
    }
}



impl std::fmt::Display for Unit {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.suffix())
    }
}

/// Error type for unit parsing.
#[derive(Debug, Clone, Error, PartialEq, Eq)]
#[error("unknown unit: '{0}' (expected: mm, mil, in, nm)")]
pub struct ParseUnitError(pub String);

impl FromStr for Unit {
    type Err = ParseUnitError;

    /// Parse a unit from a string.
    ///
    /// Accepts: "mm", "mil", "in", "inch", "nm"
    /// Case-insensitive.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::Unit;
    ///
    /// assert_eq!("mm".parse::<Unit>().unwrap(), Unit::Mm);
    /// assert_eq!("mil".parse::<Unit>().unwrap(), Unit::Mil);
    /// assert_eq!("in".parse::<Unit>().unwrap(), Unit::Inch);
    /// assert_eq!("inch".parse::<Unit>().unwrap(), Unit::Inch);
    /// assert_eq!("nm".parse::<Unit>().unwrap(), Unit::Nm);
    ///
    /// // Case insensitive
    /// assert_eq!("MM".parse::<Unit>().unwrap(), Unit::Mm);
    /// ```
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s.to_lowercase().as_str() {
            "mm" => Ok(Unit::Mm),
            "mil" | "mils" => Ok(Unit::Mil),
            "in" | "inch" | "inches" => Ok(Unit::Inch),
            "nm" => Ok(Unit::Nm),
            _ => Err(ParseUnitError(s.to_string())),
        }
    }
}

/// A dimension value with an associated unit.
///
/// This is useful for preserving the original unit in the source
/// while still being able to convert to nanometers.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
pub struct Dimension {
    /// The numeric value in the original unit.
    pub value: f64,
    /// The unit of measurement.
    pub unit: Unit,
}

impl Dimension {
    /// Create a new dimension.
    pub const fn new(value: f64, unit: Unit) -> Self {
        Dimension { value, unit }
    }

    /// Create a dimension in millimeters.
    pub const fn mm(value: f64) -> Self {
        Dimension { value, unit: Unit::Mm }
    }

    /// Create a dimension in mils.
    pub const fn mil(value: f64) -> Self {
        Dimension { value, unit: Unit::Mil }
    }

    /// Create a dimension in inches.
    pub const fn inch(value: f64) -> Self {
        Dimension { value, unit: Unit::Inch }
    }

    /// Create a dimension in nanometers.
    pub const fn nm(value: f64) -> Self {
        Dimension { value, unit: Unit::Nm }
    }

    /// Convert this dimension to nanometers.
    pub fn to_nm(self) -> Nm {
        self.unit.to_nm(self.value)
    }
}

impl std::fmt::Display for Dimension {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}{}", self.value, self.unit)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_unit_to_nm() {
        assert_eq!(Unit::Mm.to_nm(1.0).0, 1_000_000);
        assert_eq!(Unit::Mil.to_nm(1.0).0, 25_400);
        assert_eq!(Unit::Inch.to_nm(1.0).0, 25_400_000);
        assert_eq!(Unit::Nm.to_nm(1.0).0, 1);
    }

    #[test]
    fn test_unit_from_nm() {
        let nm = Nm(1_000_000);
        assert!((Unit::Mm.from_nm(nm) - 1.0).abs() < 1e-9);

        let nm = Nm(25_400);
        assert!((Unit::Mil.from_nm(nm) - 1.0).abs() < 1e-9);

        let nm = Nm(25_400_000);
        assert!((Unit::Inch.from_nm(nm) - 1.0).abs() < 1e-9);
    }

    #[test]
    fn test_unit_round_trip() {
        for unit in [Unit::Mm, Unit::Mil, Unit::Inch] {
            let original = 10.5;
            let nm = unit.to_nm(original);
            let back = unit.from_nm(nm);
            assert!((back - original).abs() < 0.001, "Round-trip failed for {:?}", unit);
        }
    }

    #[test]
    fn test_unit_parse() {
        assert_eq!("mm".parse::<Unit>().unwrap(), Unit::Mm);
        assert_eq!("MM".parse::<Unit>().unwrap(), Unit::Mm);
        assert_eq!("mil".parse::<Unit>().unwrap(), Unit::Mil);
        assert_eq!("mils".parse::<Unit>().unwrap(), Unit::Mil);
        assert_eq!("in".parse::<Unit>().unwrap(), Unit::Inch);
        assert_eq!("inch".parse::<Unit>().unwrap(), Unit::Inch);
        assert_eq!("inches".parse::<Unit>().unwrap(), Unit::Inch);
        assert_eq!("nm".parse::<Unit>().unwrap(), Unit::Nm);
    }

    #[test]
    fn test_unit_parse_error() {
        let result = "cm".parse::<Unit>();
        assert!(result.is_err());
        assert_eq!(result.unwrap_err().0, "cm");
    }

    #[test]
    fn test_dimension_to_nm() {
        let dim = Dimension::mm(10.0);
        assert_eq!(dim.to_nm().0, 10_000_000);

        let dim = Dimension::mil(100.0);
        assert_eq!(dim.to_nm().0, 2_540_000);
    }

    #[test]
    fn test_unit_suffix() {
        assert_eq!(Unit::Mm.suffix(), "mm");
        assert_eq!(Unit::Mil.suffix(), "mil");
        assert_eq!(Unit::Inch.suffix(), "in");
        assert_eq!(Unit::Nm.suffix(), "nm");
    }
}

//! AST types for CodeYourPCB DSL.
//!
//! This module defines the typed Abstract Syntax Tree (AST) nodes that are
//! produced by converting Tree-sitter's Concrete Syntax Tree (CST).
//!
//! All AST nodes carry [`Span`] information for error reporting and
//! source mapping back to the original code.
//!
//! # Example
//!
//! A typical AST structure for:
//! ```cypcb
//! version 1
//! board test { size 30mm x 20mm }
//! ```
//!
//! Would be:
//! ```rust,ignore
//! SourceFile {
//!     version: Some(1),
//!     definitions: vec![
//!         Definition::Board(BoardDef {
//!             name: Identifier { value: "test", span: ... },
//!             size: Some(SizeProperty { width: ..., height: ... }),
//!             layers: None,
//!             ...
//!         })
//!     ],
//!     span: Span { start: 0, end: 42 },
//! }
//! ```

use cypcb_core::Unit;
use serde::{Deserialize, Serialize};

/// A byte range in the source code.
///
/// Used for error reporting and source mapping. Start and end are byte offsets
/// into the source string (inclusive start, exclusive end).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct Span {
    /// Start byte offset (inclusive).
    pub start: usize,
    /// End byte offset (exclusive).
    pub end: usize,
}

impl Span {
    /// Create a new span from start and end byte offsets.
    pub const fn new(start: usize, end: usize) -> Self {
        Span { start, end }
    }

    /// Create a span that covers a single point.
    pub const fn point(pos: usize) -> Self {
        Span {
            start: pos,
            end: pos,
        }
    }

    /// Return the length of this span in bytes.
    pub const fn len(&self) -> usize {
        self.end - self.start
    }

    /// Return true if this span is empty.
    pub const fn is_empty(&self) -> bool {
        self.start >= self.end
    }

    /// Merge two spans to create a span covering both.
    pub fn merge(self, other: Span) -> Span {
        Span {
            start: self.start.min(other.start),
            end: self.end.max(other.end),
        }
    }

    /// Convert to a miette SourceSpan.
    pub fn to_miette(self) -> miette::SourceSpan {
        (self.start, self.len()).into()
    }
}

impl From<Span> for miette::SourceSpan {
    fn from(span: Span) -> Self {
        span.to_miette()
    }
}

/// The root AST node representing an entire source file.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SourceFile {
    /// Optional version declaration (e.g., `version 1`).
    pub version: Option<u32>,
    /// All top-level definitions in the file.
    pub definitions: Vec<Definition>,
    /// Span covering the entire file.
    pub span: Span,
}

/// A top-level definition in the source file.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum Definition {
    /// A board definition.
    Board(BoardDef),
    /// A component definition.
    Component(ComponentDef),
    /// A net definition.
    Net(NetDef),
    /// A custom footprint definition.
    Footprint(FootprintDef),
    /// A zone definition (keepout or copper pour).
    Zone(ZoneDef),
    /// A manual trace definition.
    Trace(TraceDef),
    /// A module definition (v2).
    Module(ModuleDef),
    /// An interface definition (v2).
    Interface(InterfaceDef),
    /// An import statement (v2).
    Import(ImportDef),
    /// An assert statement (v2).
    Assert(AssertDef),
}

impl Definition {
    /// Get the span of this definition.
    pub fn span(&self) -> Span {
        match self {
            Definition::Board(b) => b.span,
            Definition::Component(c) => c.span,
            Definition::Net(n) => n.span,
            Definition::Footprint(f) => f.span,
            Definition::Zone(z) => z.span,
            Definition::Trace(t) => t.span,
            Definition::Module(m) => m.span,
            Definition::Interface(i) => i.span,
            Definition::Import(i) => i.span,
            Definition::Assert(a) => a.span,
        }
    }
}

/// A board definition: `board name { ... }`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BoardDef {
    /// The board name (identifier).
    pub name: Identifier,
    /// Size property if specified.
    pub size: Option<SizeProperty>,
    /// Number of copper layers (2, 4, etc.).
    pub layers: Option<u8>,
    /// Stackup definition if specified.
    pub stackup: Option<StackupDef>,
    /// Span covering the entire board definition.
    pub span: Span,
}

/// Board size property: `size 30mm x 20mm`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SizeProperty {
    /// Board width.
    pub width: Dimension,
    /// Board height.
    pub height: Dimension,
    /// Span covering the size property.
    pub span: Span,
}

/// Stackup definition containing layer information.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StackupDef {
    /// List of layers in the stackup.
    pub layers: Vec<StackupLayer>,
    /// Span covering the stackup definition.
    pub span: Span,
}

/// A single layer in a stackup definition.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StackupLayer {
    /// Type of layer (copper, prepreg, etc.).
    pub layer_type: LayerType,
    /// Optional thickness of the layer.
    pub thickness: Option<Dimension>,
    /// Span covering this layer definition.
    pub span: Span,
}

/// Types of layers in a PCB stackup.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum LayerType {
    /// Copper layer for traces.
    Copper,
    /// Prepreg (pre-impregnated composite fibers).
    Prepreg,
    /// Core material.
    Core,
    /// Solder mask.
    Mask,
    /// Silkscreen.
    Silk,
}

impl LayerType {
    /// Parse a layer type from a string.
    pub fn from_str(s: &str) -> Option<Self> {
        match s {
            "copper" => Some(LayerType::Copper),
            "prepreg" => Some(LayerType::Prepreg),
            "core" => Some(LayerType::Core),
            "mask" => Some(LayerType::Mask),
            "silk" => Some(LayerType::Silk),
            _ => None,
        }
    }
}

/// A component definition: `component R1 resistor "0402" { ... }`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ComponentDef {
    /// Component reference designator (R1, C1, U1, etc.).
    pub refdes: Identifier,
    /// Type of component.
    pub kind: ComponentKind,
    /// Footprint name (e.g., "0402", "SOIC-8").
    pub footprint: StringLit,
    /// Component value if specified (e.g., "10k", "100nF").
    pub value: Option<StringLit>,
    /// Position if specified.
    pub position: Option<PositionExpr>,
    /// Rotation in degrees if specified.
    pub rotation: Option<RotationExpr>,
    /// Inline net assignments (pin.1 = VCC).
    pub net_assignments: Vec<NetAssignment>,
    /// Span covering the entire component definition.
    pub span: Span,
}

/// Types of electronic components.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ComponentKind {
    /// Resistor (R prefix).
    Resistor,
    /// Capacitor (C prefix).
    Capacitor,
    /// Inductor (L prefix).
    Inductor,
    /// Integrated circuit (U prefix).
    Ic,
    /// LED (D or LED prefix).
    Led,
    /// Connector (J prefix).
    Connector,
    /// Diode (D prefix).
    Diode,
    /// Transistor (Q prefix).
    Transistor,
    /// Crystal oscillator (Y prefix).
    Crystal,
    /// Generic component.
    Generic,
}

impl ComponentKind {
    /// Parse a component kind from a string.
    pub fn from_str(s: &str) -> Option<Self> {
        match s {
            "resistor" => Some(ComponentKind::Resistor),
            "capacitor" => Some(ComponentKind::Capacitor),
            "inductor" => Some(ComponentKind::Inductor),
            "ic" => Some(ComponentKind::Ic),
            "led" => Some(ComponentKind::Led),
            "connector" => Some(ComponentKind::Connector),
            "diode" => Some(ComponentKind::Diode),
            "transistor" => Some(ComponentKind::Transistor),
            "crystal" => Some(ComponentKind::Crystal),
            "generic" => Some(ComponentKind::Generic),
            _ => None,
        }
    }

    /// Get the expected reference designator prefix for this component kind.
    pub fn refdes_prefix(&self) -> &'static str {
        match self {
            ComponentKind::Resistor => "R",
            ComponentKind::Capacitor => "C",
            ComponentKind::Inductor => "L",
            ComponentKind::Ic => "U",
            ComponentKind::Led => "D",
            ComponentKind::Connector => "J",
            ComponentKind::Diode => "D",
            ComponentKind::Transistor => "Q",
            ComponentKind::Crystal => "Y",
            ComponentKind::Generic => "X",
        }
    }
}

/// Position expression: `at 10mm, 8mm`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PositionExpr {
    /// X coordinate.
    pub x: Dimension,
    /// Y coordinate.
    pub y: Dimension,
    /// Span covering the position expression.
    pub span: Span,
}

/// Rotation expression: `rotate 90` or `rotate 90deg`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RotationExpr {
    /// Rotation angle in degrees.
    pub angle: f64,
    /// Span covering the rotation expression.
    pub span: Span,
}

/// Inline net assignment: `pin.1 = VCC`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct NetAssignment {
    /// Pin identifier (number or name).
    pub pin: PinId,
    /// Net name to assign.
    pub net: Identifier,
    /// Span covering the assignment.
    pub span: Span,
}

/// A net definition: `net VCC { J1.1, R1.1 }`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct NetDef {
    /// Net name.
    pub name: Identifier,
    /// Optional constraints (width, clearance).
    pub constraints: Option<NetConstraints>,
    /// List of pin references connected to this net.
    pub connections: Vec<PinRef>,
    /// Span covering the entire net definition.
    pub span: Span,
}

/// Net constraints: `[width 0.3mm, clearance 0.2mm, current 500mA]`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct NetConstraints {
    /// Trace width constraint.
    pub width: Option<Dimension>,
    /// Clearance constraint.
    pub clearance: Option<Dimension>,
    /// Current carrying requirement (for IPC-2221 calculation).
    pub current: Option<CurrentValue>,
    /// Span covering the constraint block.
    pub span: Span,
}

/// Current value with unit: `500mA` or `2A`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CurrentValue {
    /// Numeric value.
    pub value: f64,
    /// Unit of current measurement.
    pub unit: CurrentUnit,
    /// Span covering the current value.
    pub span: Span,
}

impl CurrentValue {
    /// Create a new current value.
    pub fn new(value: f64, unit: CurrentUnit, span: Span) -> Self {
        CurrentValue { value, unit, span }
    }

    /// Convert to milliamps.
    pub fn to_milliamps(&self) -> f64 {
        match self.unit {
            CurrentUnit::Milliamps => self.value,
            CurrentUnit::Amps => self.value * 1000.0,
        }
    }

    /// Convert to amps.
    pub fn to_amps(&self) -> f64 {
        match self.unit {
            CurrentUnit::Milliamps => self.value / 1000.0,
            CurrentUnit::Amps => self.value,
        }
    }
}

impl std::fmt::Display for CurrentValue {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}{}", self.value, self.unit)
    }
}

/// Unit of current measurement.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum CurrentUnit {
    /// Milliamps (mA).
    Milliamps,
    /// Amps (A).
    Amps,
}

impl CurrentUnit {
    /// Parse a current unit from a string.
    pub fn from_str(s: &str) -> Option<Self> {
        match s {
            "mA" => Some(CurrentUnit::Milliamps),
            "A" => Some(CurrentUnit::Amps),
            _ => None,
        }
    }
}

impl std::fmt::Display for CurrentUnit {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            CurrentUnit::Milliamps => write!(f, "mA"),
            CurrentUnit::Amps => write!(f, "A"),
        }
    }
}

/// A pin reference: `J1.1` or `U1.VCC`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PinRef {
    /// Component reference designator.
    pub component: Identifier,
    /// Pin identifier (number or name).
    pub pin: PinId,
    /// Span covering the pin reference.
    pub span: Span,
}

/// A pin identifier: number or name.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(untagged)]
pub enum PinId {
    /// Numeric pin (1, 2, 3, ...).
    Number(u32),
    /// Named pin (VCC, GND, anode, cathode, ...).
    Name(String),
}

impl PinId {
    /// Create a numeric pin ID.
    pub fn number(n: u32) -> Self {
        PinId::Number(n)
    }

    /// Create a named pin ID.
    pub fn name(s: impl Into<String>) -> Self {
        PinId::Name(s.into())
    }
}

impl std::fmt::Display for PinId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            PinId::Number(n) => write!(f, "{}", n),
            PinId::Name(s) => write!(f, "{}", s),
        }
    }
}

/// An identifier token.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Identifier {
    /// The identifier text.
    pub value: String,
    /// Span of the identifier.
    pub span: Span,
}

impl Identifier {
    /// Create a new identifier.
    pub fn new(value: impl Into<String>, span: Span) -> Self {
        Identifier {
            value: value.into(),
            span,
